import { expect, test } from "@playwright/test";

// #504 (F4b): one reference per example of the gallery section «Scelte e
// persone», in the light and in the dark theme, on mobile and desktop. The
// references are generated by the visual tester (`visual-baseline`).

test.use({
  locale: "it-IT",
  timezoneId: "Europe/Rome",
  reducedMotion: "reduce",
});

const IDS = [
  "ds-scelte-schede",
  "ds-scelte-schede-errore",
  "ds-scelte-tessere",
  "ds-pastiglie",
  "ds-pastiglie-persone",
  "ds-per-chi",
  "ds-per-chi-dieci",
  "ds-per-chi-caricamento",
  "ds-giorni",
  "ds-filtri",
  "ds-spunta",
  "ds-volti",
  "ds-volti-vuoto",
  "ds-foto-e-pila",
  "ds-aiutante",
  "ds-tessere-spazi",
  "ds-tessere-nest",
  "ds-tag-allerta",
];

for (const scheme of ["light", "dark"] as const) {
  test.describe(`scelte e persone, tema ${scheme}`, () => {
    test.beforeEach(async ({ page }) => {
      await page.emulateMedia({ colorScheme: scheme });
      await page.goto("/design-system");
      await page.evaluate(() => document.fonts.ready);
      await expect(page.locator("#scelte-persone")).toBeVisible();
    });

    for (const id of IDS) {
      test(`#504: esempio ${id}`, async ({ page }) => {
        // The example is the figure around the element with the test id.
        const example = page
          .getByTestId(id)
          .locator("xpath=ancestor::figure[1]");
        await example.scrollIntoViewIfNeeded();
        await page.mouse.move(0, 0);
        await expect(example).toHaveScreenshot(`esempio-${id}-${scheme}.png`);
      });
    }
  });
}
